import React from 'react';

import { Link } from 'react-router-dom';

import HikingBadge from '@apps/Hiking/@components/HikingBadge';
import { getOneProductStat } from '@apps/Products/@services/products.service';
import { IProductStat } from '@apps/Products/@types/products.types';
import PageLoader from '@components/PageLoader';
import { formatFinance } from '@helpers/formatHelper';
import { fullNameForUser } from '@helpers/user.helper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohAva from '@ui-kit/Ava';
import Empty from '@ui-kit/Empty';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';

const ProductOneStat: React.FC<{ id_product: number }> = ({ id_product }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IProductStat>();

  const load = React.useCallback(async () => {
    try {
      setIsLoading(true);
      const res = await getOneProductStat(id_product);
      setData(res);
    } catch (e) {
      setErr(e as Error);
    } finally {
      setIsLoading(false);
    }
  }, [id_product]);

  React.useEffect(() => {
    load();
  }, [load]);

  if (isLoading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  if (!data) return <div>Has no data</div>;

  return (
    <div>
      <PohRow>
        <PohCol sm={12}>
          <h3>Рецепты</h3>
          <PohList
            flush
            data={data?.recipes.map((recipe) => {
              return {
                key: recipe.id,
                action: true,
                to: `/recipes/${recipe.id}`,
                as: Link,
                children: (
                  <div className="d-flex align-items-center ms-n2 ny-n3">
                    <div>
                      <strong title={recipe.recipe.name}>{recipe.recipe.name}</strong>
                    </div>
                    <small className="ms-auto">{recipe.amount}&thinsp;г.</small>
                  </div>
                ),
              };
            })}
          />
        </PohCol>
        <PohCol sm={6}>
          <h3>Покупки</h3>
          <PohList
            flush
            data={data.shopping.map((shopping) => {
              return {
                key: shopping.id,
                children: (
                  <div className="d-flex align-items-center ms-n2 ny-n3">
                    <PohAva
                      src={shopping.user.photo}
                      alt={fullNameForUser(shopping.user)}
                      className="me-2"
                    />
                    <div>
                      <strong title={shopping.date.toLocaleString()}>
                        {shopping.date.toLocaleString()}
                      </strong>
                      <br />
                      <strong>{shopping.price ? formatFinance(shopping.price) : ''}</strong>
                      <small>
                        <em>{shopping.comment}</em>
                      </small>
                    </div>
                    <Link to={`/hiking/${shopping.hiking.id}`} className="ms-auto">
                      <HikingBadge
                        className=" flex-row-reverse text-end"
                        hiking={shopping.hiking}
                      />
                    </Link>
                  </div>
                ),
              };
            })}
          />
        </PohCol>
        <PohCol sm={6}>
          <h3>Чеки</h3>
          <PohList
            flush
            data={data.receipt_items.map((item) => {
              return {
                key: item.id,
                as: Link,
                to: `/hiking/${item.hiking.id}/finances/${item.id_receipt}`,
                children: (
                  <div className="d-flex align-items-center ms-n2 ny-n3">
                    <div>
                      <strong>{item.item.name}</strong>
                      <br />
                      <strong>
                        <small>{formatFinance(item.item.cost)}</small>&thinsp;*&thinsp;
                        <small>{item.item.amount}</small>&thinsp;=&thinsp;
                        {formatFinance(item.item.cost * item.item.amount)}
                      </strong>
                    </div>
                    <Link to={`/hiking/${item.hiking.id}`} className="ms-auto">
                      <HikingBadge className=" flex-row-reverse text-end" hiking={item.hiking} />
                    </Link>
                  </div>
                ),
              };
            })}
          />
        </PohCol>
        <PohCol sm={12}>
          <h3>Назначения</h3>
          {data.force.length === 0 ? (
            <Empty>Пусто</Empty>
          ) : (
            <PohList
              flush
              data={data.force.map((force) => {
                return {
                  key: force.id,
                  children: (
                    <div className="d-flex align-items-center ms-n2 ny-n3">
                      <PohAva
                        src={force.user.photo}
                        alt={fullNameForUser(force.user)}
                        className="me-2"
                      />
                      <div>
                        <strong title={fullNameForUser(force.user)}>
                          {fullNameForUser(force.user)}
                        </strong>
                      </div>
                      <Link to={`/hiking/${force.hiking.id}`} className="ms-auto">
                        <HikingBadge className=" flex-row-reverse text-end" hiking={force.hiking} />
                      </Link>
                    </div>
                  ),
                };
              })}
            />
          )}
        </PohCol>

        <PohCol sm={6}>
          <h3>Замены (с)</h3>
          {data.source_product.length === 0 ? (
            <Empty>Пусто</Empty>
          ) : (
            <PohList
              flush
              data={data.source_product.map((rep) => {
                return {
                  key: rep.id,
                  children: (
                    <div className="d-flex align-items-center ms-n2 ny-n3">
                      <div>
                        <strong>{rep.product.name}</strong>
                        <br />
                        <small>
                          <em>{rep.comment}</em>
                        </small>
                      </div>
                      <Link to={`/hiking/${rep.hiking.id}`} className="ms-auto">
                        <HikingBadge className=" flex-row-reverse text-end" hiking={rep.hiking} />
                      </Link>
                    </div>
                  ),
                };
              })}
            />
          )}
        </PohCol>
        <PohCol sm={6}>
          <h3>Замены (на)</h3>
          {data.target_product.length === 0 ? (
            <Empty>Пусто</Empty>
          ) : (
            <PohList
              flush
              data={data.target_product.map((rep) => {
                return {
                  key: rep.id,
                  children: (
                    <div className="d-flex align-items-center ms-n2 ny-n3">
                      <div>
                        <strong>{rep.product.name}</strong>
                        <br />
                        <small>
                          <em>{rep.comment}</em>
                        </small>
                      </div>
                      <Link to={`/hiking/${rep.hiking.id}`} className="ms-auto">
                        <HikingBadge className=" flex-row-reverse text-end" hiking={rep.hiking} />
                      </Link>
                    </div>
                  ),
                };
              })}
            />
          )}
        </PohCol>
      </PohRow>
    </div>
  );
};

export default ProductOneStat;
